#include <cstdint>
#include <string>

static bool near(std::uint64_t address, std::uint64_t pattern)
{
    return address >= pattern && address - pattern <= 0xFFF;
}

static bool isFill(std::uint64_t address, std::uint32_t pattern32)
{
    const std::uint64_t full{ (static_cast<std::uint64_t>(pattern32) << 32) | pattern32 };
    return near(address, full) || near(address, pattern32);
}

std::string diagnose(std::uint64_t address)
{
    if (address < 0x10000) return "null pointer";
    if (isFill(address, 0xCCCCCCCCu)) return "uninitialised stack";
    if (isFill(address, 0xCDCDCDCDu)) return "uninitialised heap";
    if (isFill(address, 0xDDDDDDDDu)) return "freed heap";
    if (isFill(address, 0xFEEEFEEEu)) return "freed (Windows heap)";
    if (isFill(address, 0xFDFDFDFDu)) return "guard bytes";
    return "unknown";
}

unitTests:
TEST("null and near null") {
    CHECK_EQ(diagnose(0), std::string("null pointer"));
    CHECK_EQ(diagnose(0x18), std::string("null pointer"));
    CHECK_EQ(diagnose(0xFFFF), std::string("null pointer"));
    CHECK_EQ(diagnose(0x10000), std::string("unknown"));
}
TEST("64-bit fill patterns") {
    CHECK_EQ(diagnose(0xCCCCCCCCCCCCCCCCull), std::string("uninitialised stack"));
    CHECK_EQ(diagnose(0xCDCDCDCDCDCDCDCDull), std::string("uninitialised heap"));
    CHECK_EQ(diagnose(0xDDDDDDDDDDDDDDDDull), std::string("freed heap"));
    CHECK_EQ(diagnose(0xFEEEFEEEFEEEFEEEull), std::string("freed (Windows heap)"));
    CHECK_EQ(diagnose(0xFDFDFDFDFDFDFDFDull), std::string("guard bytes"));
}
TEST("patterns plus a member offset") {
    CHECK_EQ(diagnose(0xDDDDDDDDDDDDDE05ull), std::string("freed heap"));
    CHECK_EQ(diagnose(0xCCCCCCCCCCCCCCD4ull), std::string("uninitialised stack"));
    CHECK_EQ(diagnose(0xCDCDCDCDCDCDDDCDull), std::string("unknown"));
    CHECK_EQ(diagnose(0xDDDDDDDDDDDDDDDCull), std::string("unknown"));
}
TEST("32-bit patterns") {
    CHECK_EQ(diagnose(0xCDCDCDCDull), std::string("uninitialised heap"));
    CHECK_EQ(diagnose(0xDDDDDDE1ull), std::string("freed heap"));
    CHECK_EQ(diagnose(0xFEEEFEEEull), std::string("freed (Windows heap)"));
}
TEST("ordinary addresses") {
    CHECK_EQ(diagnose(0x000001C4B2E8F0A0ull), std::string("unknown"));
    CHECK_EQ(diagnose(0x00007FF61A2B5000ull), std::string("unknown"));
}

